    [4436]={name="Jewel-encrusted Sash",quality=2,ilvl=23,reqLevel=18,sourceType="rare_npc",instructions="Drops from Dalaran Spellscribe.",zone="Silverpine Forest",npc="Dalaran Spellscribe"},
    [4438]={name="Pugilist Bracers",quality=3,ilvl=30,reqLevel=25,sourceType="raid_trash",instructions="Drops from trash in Razorfen Kraul.",zone="Razorfen Kraul",zoneOpen=true},
    [4439]={name="Bruiser Club",quality=2,ilvl=24,reqLevel=19,sourceType="rare_npc",instructions="Drops from Rot Hide Bruiser.",zone="Alterac Mountains",npc="Rot Hide Bruiser"},
    [4443]={name="Grim Pauldrons",quality=2,ilvl=36,reqLevel=27,sourceType="quest_reward",instructions="Reward from the quest 'To Steal From Thieves'. Pick it over the other reward choices. Starts with Genavie Callow in Undercity. Objective: Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.",zone="Undercity",questName="To Steal From Thieves",lore="The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed! My family is gone, taken by the plague."},
    [4444]={name="Black Husk Shield",quality=2,ilvl=26,reqLevel=21,sourceType="rare_npc",instructions="Drops from Leech Widow.",zone="Wetlands",npc="Leech Widow",proc="Use: Attempts to cure 1 poison effect on the target, and 1 more poison effect every 2 seconds for 8 sec. (5 Min Cooldown)"},
    [4445]={name="Flesh Carver",quality=2,ilvl=25,reqLevel=20,sourceType="rare_npc",instructions="Drops from Snarlmane.",zone="Silverpine Forest",npc="Snarlmane"},
