    [12000]={name="Limb Cleaver",quality=2,ilvl=55,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'Hurley Blackbreath'. Pick it over the other reward choices. Starts with Ragnar Thunderbrew in Dun Morogh. Objective: Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.",zone="Blackrock Depths",questName="Hurley Blackbreath",lore="The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager. The villains! They don't deserve such a fine brew!, I have a tough task for you."},
    [12006]={name="Meadow Ring",quality=2,ilvl=22,reqLevel=17,sourceType="world_drop",instructions="World drop around level 17-24.",zone="The Barrens",zoneOpen=true},
