    [18022]={name="Royal Seal of Alexis",quality=3,ilvl=62,reqLevel=56,sourceType="quest_reward",instructions="Reward from the quest 'Ramstein'. Pick it over the other reward choices.",zone="Stratholme",questName="Ramstein",lore="I was overwhelmed. On this very stead, I stood... held my ground in defense of Lordaeron. The farm and all on it were waylaid by a gigantic wave of Scourge."},
